/* Drag a shelf without changing the order of its books or duplicating people. */
'use strict';
const shelfMotionStates=new WeakMap();
let shelfGesture=null;
const shelfReducedMotion=()=>window.matchMedia('(prefers-reduced-motion: reduce)').matches;
function shelfMotionState(shelf){let value=shelfMotionStates.get(shelf);if(!value){value={frame:0,drift:0,lean:0,suppressClickUntil:0};shelfMotionStates.set(shelf,value)}return value}
function paintShelfMotion(shelf,drift=0,lean=0){const v=shelfMotionState(shelf);v.drift=drift;v.lean=lean;shelf.style.setProperty('--shelf-drift',drift.toFixed(2)+'px');shelf.style.setProperty('--shelf-lean',lean.toFixed(2)+'deg')}
function naturalShelfMax(shelf){const rail=shelf.querySelector('.standing-books'),style=getComputedStyle(shelf);return Math.max(0,rail.offsetWidth+parseFloat(style.paddingLeft)+parseFloat(style.paddingRight)-shelf.clientWidth)}
function stopShelfMotion(shelf){const v=shelfMotionState(shelf);cancelAnimationFrame(v.frame);v.frame=0;shelf.classList.remove('is-flowing','is-dragging');paintShelfMotion(shelf)}
function releaseShelf(shelf,velocity=0){const v=shelfMotionState(shelf);cancelAnimationFrame(v.frame);shelf.classList.remove('is-dragging');if(shelfReducedMotion()){stopShelfMotion(shelf);return}let last=performance.now();const tick=now=>{if(!shelf.isConnected){stopShelfMotion(shelf);return}const dt=Math.min(32,now-last);last=now;const max=naturalShelfMax(shelf),raw=shelf.scrollLeft+velocity*dt,next=Math.max(0,Math.min(max,raw));shelf.scrollLeft=next;if(raw!==next){v.drift=Math.max(-60,Math.min(60,v.drift-(raw-next)*.2));velocity=0}else velocity*=Math.pow(.93,dt/16);paintShelfMotion(shelf,v.drift*Math.exp(-dt/80),v.lean*Math.exp(-dt/100));if(Math.abs(velocity)<.025&&Math.abs(v.drift)<.3&&Math.abs(v.lean)<.03){stopShelfMotion(shelf);return}v.frame=requestAnimationFrame(tick)};shelf.classList.add('is-flowing');v.frame=requestAnimationFrame(tick)}
function stepShelf(shelf,direction){stopShelfMotion(shelf);const max=naturalShelfMax(shelf),start=shelf.scrollLeft,end=Math.max(0,Math.min(max,start+direction*Math.max(130,shelf.clientWidth*.65)));if(shelfReducedMotion()){shelf.scrollLeft=end;return}const v=shelfMotionState(shelf),began=performance.now(),atEdge=Math.abs(end-start)<1;shelf.classList.add('is-flowing');const tick=now=>{if(!shelf.isConnected){stopShelfMotion(shelf);return}const t=Math.min(1,(now-began)/480),ease=1-Math.pow(1-t,3);shelf.scrollLeft=start+(end-start)*ease;paintShelfMotion(shelf,atEdge?-direction*45*Math.sin(Math.PI*t):0,-direction*1.2*Math.sin(Math.PI*t));if(t<1)v.frame=requestAnimationFrame(tick);else stopShelfMotion(shelf)};v.frame=requestAnimationFrame(tick)}
document.addEventListener('pointerdown',event=>{const shelf=event.target.closest('.shelf-scroll');if(!shelf||event.button!==0||event.isPrimary===false||event.target.closest('.shelf-bookmark,.shelf-topic'))return;stopShelfMotion(shelf);shelfGesture={shelf,pointerId:event.pointerId,x:event.clientX,y:event.clientY,scroll:shelf.scrollLeft,lastX:event.clientX,lastTime:performance.now(),velocity:0,dragged:false}});
document.addEventListener('pointermove',event=>{const g=shelfGesture;if(!g||event.pointerId!==g.pointerId)return;const dx=event.clientX-g.x,dy=event.clientY-g.y;if(!g.dragged){if(Math.abs(dy)>8&&Math.abs(dy)>Math.abs(dx)){shelfGesture=null;return}if(Math.abs(dx)<7)return;g.dragged=true;g.shelf.setPointerCapture(event.pointerId);g.shelf.classList.add('is-dragging','is-flowing')}event.preventDefault();const now=performance.now(),dt=Math.max(1,now-g.lastTime);g.velocity=g.velocity*.55+((g.lastX-event.clientX)/dt)*.45;g.lastX=event.clientX;g.lastTime=now;const max=naturalShelfMax(g.shelf),raw=g.scroll-dx,clamped=Math.max(0,Math.min(max,raw));g.shelf.scrollLeft=clamped;paintShelfMotion(g.shelf,shelfReducedMotion()?0:Math.max(-65,Math.min(65,-(raw-clamped)*.3)),shelfReducedMotion()?0:Math.max(-1.8,Math.min(1.8,-g.velocity*.9)));},{passive:false});
function finishShelfGesture(event){const g=shelfGesture;if(!g||event.pointerId!==g.pointerId)return;shelfGesture=null;if(g.shelf.hasPointerCapture(event.pointerId))g.shelf.releasePointerCapture(event.pointerId);if(!g.dragged)return;shelfMotionState(g.shelf).suppressClickUntil=performance.now()+420;releaseShelf(g.shelf,performance.now()-g.lastTime>90||event.type==='pointercancel'?0:g.velocity)}
document.addEventListener('pointerup',finishShelfGesture);document.addEventListener('pointercancel',finishShelfGesture);
document.addEventListener('click',event=>{const shelf=event.target.closest('.shelf-scroll');if(shelf&&performance.now()<shelfMotionState(shelf).suppressClickUntil){event.preventDefault();event.stopImmediatePropagation()}},true);
document.addEventListener('click',event=>{const button=event.target.closest('[data-shelf-step]');if(!button)return;const shelf=button.closest('.shelf-bay')?.querySelector('.shelf-scroll');if(shelf)stepShelf(shelf,Number(button.dataset.shelfStep))});
document.addEventListener('keydown',event=>{if(!event.target.matches('.shelf-scroll')||!['ArrowLeft','ArrowRight'].includes(event.key))return;event.preventDefault();stepShelf(event.target,event.key==='ArrowRight'?1:-1)});
document.addEventListener('dragstart',event=>{if(event.target.closest('.shelf-scroll'))event.preventDefault()});
